  readonly pkg: string;
}> = ({ pkg }) => {
  if (pkg === undefined) {
    throw new Error("pkg is undefined");
  }

  const packages = pkg
    .split(" ")
    .map((p) => {
      if (p.startsWith("@remotion")) {
        return `${p}@${VERSION}`;
      }

      return p;
    })
    .join(" ");

  const isRemotionPackage = packages.includes("remotion");

  return (
    <div>
      <Tabs
        defaultValue="npm"
        values={[
          { label: "npm", value: "npm" },
          { label: "yarn", value: "yarn" },
          { label: "pnpm", value: "pnpm" },
          { label: "bun", value: "bun" },
