        <TabItem value="npm">
          <LightAndDark text={`npm i --save-exact ${packages}`} />
        </TabItem>
        <TabItem value="pnpm">
          <LightAndDark text={`pnpm i ${packages}`} />
        </TabItem>
        <TabItem value="bun">
          <LightAndDark text={`bun i ${packages}`} />
        </TabItem>
        <TabItem value="yarn">
          <LightAndDark text={`yarn --exact add ${packages}`} />
        </TabItem>
      </Tabs>
      {isRemotionPackage ? (
        <>
          This assumes you are currently using v{VERSION} of Remotion.
          <br />
          Also update <code>remotion</code> and all <code>`@remotion/*`</code>{" "}
          packages to the same version.
          <br />
          Remove all <code>^</code> character in front of the version numbers of
          it as it can lead to a version conflict.
        </>
      ) : null}
    </div>
  );
};

import {GoogleAuth} from 'google-auth-library';
import {
	getProjectId,
	isInCloudTask,
} from '../../functions/helpers/is-in-cloud-task';

export const getAuthClientForUrl = async (url: string) => {
	let auth = new GoogleAuth();
	if (isInCloudTask()) {
		auth = new GoogleAuth({
			projectId: getProjectId(),
		});
	} else {
		auth = new GoogleAuth({
			projectId: process.env.REMOTION_GCP_PROJECT_ID,
			credentials: {
				client_email: process.env.REMOTION_GCP_CLIENT_EMAIL,
				private_key: process.env.REMOTION_GCP_PRIVATE_KEY,
			},
		});
	}

	const client = await auth.getIdTokenClient(url);
	return client;
};

